definition.script:
pipeline {
    agent { label 'linux' }
    options {
        dynamicQueuePriority(level: 'HIGH')
        timestamps()
        buildDiscarder(logRotator(numToKeepStr: '30'))
        timeout(time: 30, unit: 'MINUTES')
    }
    parameters {
        string(name: 'BRANCH', defaultValue: 'main', description: 'Branch to build')
        string(name: 'COMMIT', defaultValue: '', description: 'Commit SHA or empty for head')
    }
    stages {
        stage('Checkout') {
            steps {
                checkout([$class: 'GitSCM',
                          branches: [[name: params.COMMIT ?: params.BRANCH]],
                          userRemoteConfigs: [[url: 'https://github.com/haiderali-dev/payment-service.git']]])
            }
        }
        stage('Build') {
            steps { sh './scripts/build.sh' }
        }
        stage('Unit tests') {
            steps { sh './scripts/test.sh unit' }
        }
        stage('Deploy') {
            steps { sh './deploy.sh staging' }
        }
    }
    post {
        always { cleanWs() }
    }
}
